<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {onBeforeRouteLeave} from 'vue-router';
import {api,loadCatalog} from '../lib/api';import {confirmAction} from '../lib/dialog';import {readDraft,writeDraft,clearDraft,protectUnload} from '../lib/edit-protection';
import type {Category,RoleOption} from '../../shared/models';
const data=ref<{categories:Category[];roles:RoleOption[]}>(),busy=ref(false),error=ref(''),notice=ref(''),base=ref(''),version=ref<number|null>(null);
const blank=()=>({category_id:null as string|null,name:'',platform_id:'',staff_limit:null as number|null,evidence_url:'',labels:''});const form=ref(blank());let ready=false;
const dirty=computed(()=>!!base.value&&JSON.stringify(form.value)!==base.value);
async function load(){data.value=await api('/api/admin/bili-role-config');}
function select(id:string){const c=data.value?.categories.find(c=>c.id===id);version.value=c?.version??null;if(!c){form.value=blank();return;}const rows=data.value!.roles.filter(r=>r.category_id===c.id),latest=Math.max(0,...rows.map(r=>r.dictionary_version));form.value={category_id:c.id,name:c.name,platform_id:c.platform_id??'',staff_limit:c.staff_limit,evidence_url:rows.find(r=>r.dictionary_version===latest)?.evidence_url??'',labels:rows.filter(r=>r.dictionary_version===latest).map(r=>r.label).join('\n')};}
function persist(){if(!ready)return;if(dirty.value)writeDraft('dictionary',{form:form.value,version:version.value});else clearDraft('dictionary');}watch(form,persist,{deep:true,flush:'sync'});
async function pick(event:Event){const input=event.target as HTMLSelectElement;try{if(dirty.value&&!await confirmAction('切换分区将放弃当前修改，确定切换？'))return;ready=false;select(input.value);base.value=JSON.stringify(form.value);ready=true;persist();error.value='';notice.value='';}finally{input.value=form.value.category_id??'';}}
async function reload(){if(dirty.value&&!await confirmAction('放弃本机修改，重新读取分区与职务？'))return;ready=false;await load();select(form.value.category_id??'');base.value=JSON.stringify(form.value);ready=true;persist();error.value='';notice.value='已读取最新资料';}
let operation='';let lastPayload='';
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const value={...form.value,expectedVersion:version.value,platform_id:form.value.platform_id||null,staff_limit:form.value.staff_limit?Number(form.value.staff_limit):null,labels:form.value.labels.split('\n').map(s=>s.trim()).filter(Boolean)},serialized=JSON.stringify(value);if(serialized!==lastPayload){operation=crypto.randomUUID();lastPayload=serialized;}const r=await api<{id:string;version:number}>('/api/admin/bili-role-config',{...value,operation_id:operation},'PUT');ready=false;await load();select(r.id);base.value=JSON.stringify(form.value);clearDraft('dictionary');ready=true;await loadCatalog();notice.value='分区已保存。';}catch(e){error.value=(e as Error).message;persist();}finally{busy.value=false;}}
let deletionOperation='',deletionPayload='';
async function remove(){if(busy.value||!form.value.category_id||!version.value)return;busy.value=true;try{if(!await confirmAction('删除此分区及其职务？'+(dirty.value?'本机未保存的修改也会放弃。':'')+'历史投稿记录会保留。'))return;error.value='';notice.value='';const value={category_id:form.value.category_id,expectedVersion:version.value},serialized=JSON.stringify(value);if(serialized!==deletionPayload){deletionOperation=crypto.randomUUID();deletionPayload=serialized;}await api('/api/admin/bili-role-config',{...value,operation_id:deletionOperation},'DELETE');ready=false;await load();select('');base.value=JSON.stringify(form.value);clearDraft('dictionary');ready=true;await loadCatalog();notice.value='分区已删除，历史投稿记录保留。';}catch(e){error.value=(e as Error).message;persist();}finally{busy.value=false;}}
onMounted(async()=>{try{await load();select('');base.value=JSON.stringify(form.value);const old=readDraft<{form:ReturnType<typeof blank>;version:number|null}>('dictionary');if(old&&await confirmAction('恢复本机未保存的分区与职务资料？')){select(old.form.category_id??'');base.value=JSON.stringify(form.value);form.value=old.form;version.value=old.version;notice.value='已恢复本机未保存的资料。';}ready=true;persist();}catch(e){error.value=(e as Error).message;}});
protectUnload(()=>dirty.value||busy.value);onBeforeRouteLeave(async()=>!busy.value&&(!dirty.value||await confirmAction('分区与职务尚未保存，本机草稿会保留。确定离开？')));
</script>
<template><div class="page"><header class="page-head"><div><h1>分区与职务</h1><p class="muted">维护 B站分区及对应制作职务。保存后即可用于投稿。</p></div></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><p v-if="dirty" class="alert warning">有未保存的修改。</p><section class="paper"><FieldLabel>已有分区<select :value="form.category_id??''" :disabled="busy" @change="pick"><option value="">＋ 新建分区</option><option v-for="c in data?.categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></FieldLabel><form id="dictionary-form" @submit.prevent="save"><fieldset :disabled="busy||!data"><FieldLabel>分区名称<input v-model="form.name" required maxlength="100"></FieldLabel><div class="grid two"><FieldLabel>平台分区 ID<input v-model="form.platform_id" maxlength="100"></FieldLabel><FieldLabel>人员上限（留空表示未确认）<input v-model.number="form.staff_limit" type="number" min="1" max="10000"></FieldLabel></div><FieldLabel>核实证据链接<input v-model="form.evidence_url" required type="url" maxlength="2000" placeholder="https://…"></FieldLabel><FieldLabel>职务标签（每行一个）<textarea v-model="form.labels" required rows="8" placeholder="填写该分区的制作职务，每行一个"></textarea></FieldLabel><p class="hint">保存前请核对分区和职务。删除后不再用于新的投稿，历史投稿记录保留。</p><PageActions><button v-if="form.category_id" type="button" class="danger" :disabled="busy" @click="remove">删除分区</button><button type="button" :disabled="busy" @click="reload">重新读取</button><button class="primary" type="submit" form="dictionary-form" :disabled="busy||!data">{{ busy?'正在保存…':'保存分区' }}</button></PageActions></fieldset></form></section></div></template>
